import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.next();
        char initialChar = input.charAt(0);
        String modified = input.substring(1);
        int position = modified.indexOf("at");
        if (position != -1) {
            modified = modified.substring(0, position) + "@" + modified.substring(position + 2);
        }
        int dotIndex;
        while ((dotIndex = modified.indexOf("dot")) != -1 && dotIndex != modified.length() - 3) {
            modified = modified.substring(0, dotIndex) + "." + modified.substring(dotIndex + 3);
        }
        System.out.print(initialChar + modified);
        scanner.close();
    }
}
